/* Focused owner receiving of the two PR38 worksheet fixes on the native app.
 * node probe.cjs SOURCE_ROOT NEW_OUTPUT_DIRECTORY
 * TT_REVIEW_PYTHON, TT_REVIEW_PYTHONPATH, TT_REVIEW_PLAYWRIGHT, TT_REVIEW_CHROMIUM
 * choose existing runtimes. No packages, providers or account changes.
 */
const assert = require('node:assert/strict');
const fs = require('node:fs'), path = require('node:path'), crypto = require('node:crypto'), net = require('node:net');
const { spawn, spawnSync } = require('node:child_process');
const source = fs.realpathSync(process.argv[2]), output = path.resolve(process.argv[3]);
fs.mkdirSync(output); fs.mkdirSync(path.join(output,'tmp')); process.env.TMPDIR=path.join(output,'tmp');
const python=process.env.TT_REVIEW_PYTHON || '/opt/codex/runtimes/codex-primary-runtime/dependencies/python/bin/python3';
const pythonPath=process.env.TT_REVIEW_PYTHONPATH || '/workspace/scratch/60b2c08feb01/suite-venv/lib/python3.12/site-packages';
const { chromium }=require(process.env.TT_REVIEW_PLAYWRIGHT || '/opt/codex/runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');
const chrome=process.env.TT_REVIEW_CHROMIUM || '/tmp/hamon-project-browser-ce7eb129730f/portable-153/chromium';
const names=['app.py','agent.py','constraints.py','personas.py','qloo_client.py','fixtures/qloo_fixtures.json','static/app.js','static/index.html','static/style.css','static/calendar.js','static/calendar.css','static/plan-request.js','static/week_plan.mjs','static/week_file.mjs','static/venue_followup.mjs','static/venue_followup.css'];
const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const pins=()=>Object.fromEntries(names.map(n=>[n,sha(fs.readFileSync(path.join(source,n)))]));
const report={schema:'tastetable.owner-two-fix-focused.v1',started:new Date().toISOString(),sourceRoot:source,sourceBefore:pins(),probeSha256:sha(fs.readFileSync(__filename)),node:process.version,groups:[],nativeResponses:[],served:[],downloads:[],externalRequests:[],pageErrors:[],requestFailures:[]};
const env={...process.env,PYTHONPATH:pythonPath,PYTHONDONTWRITEBYTECODE:'1',TASTETABLE_LIVE:'0',QLOO_API_KEY:'',QLOO_BASE_URL:'http://127.0.0.1:0',TASTETABLE_LLM_BASE_URL:''};
let server,browser,serverLog='',origin;const responseTasks=[];
function retain(name,b){fs.writeFileSync(path.join(output,name),b,{flag:'wx'});return{file:name,bytes:Buffer.byteLength(b),sha256:sha(Buffer.from(b))};}
async function group(name,fn){let context;const observed={};try{context=await browser.newContext({viewport:{width:1180,height:960},acceptDownloads:true});await context.route('**/*',route=>{if(new URL(route.request().url()).origin===origin)return route.continue();report.externalRequests.push(route.request().url());return route.abort();});const page=await context.newPage();page.on('pageerror',e=>report.pageErrors.push(e.message));page.on('requestfailed',r=>report.requestFailures.push({url:r.url(),error:r.failure()?.errorText}));page.on('response',r=>{if(r.url().startsWith(origin+'/static/'))responseTasks.push(r.body().then(b=>report.served.push({path:new URL(r.url()).pathname.slice(1),status:r.status(),sha256:sha(b)})).catch(e=>report.requestFailures.push({url:r.url(),error:e.message})));});await page.goto(origin);const responseWaiting=page.waitForResponse(r=>r.url().includes('/api/plan/sample/')&&r.request().method()==='POST');await page.locator('#sampleBtn').click();const response=await responseWaiting,b=await response.body();const label=report.groups.length+1;report.nativeResponses.push({status:response.status(),...retain('native-plan-'+label+'.json',b)});assert.equal(response.status(),200);await page.locator('#venueFollowup').waitFor({state:'visible'});await page.locator('#weekDate').fill('2026-12-28');await page.locator('#weekDate').dispatchEvent('change');const visits=page.locator('#venueFollowup .contact-visit');assert.ok(await visits.count()>0);await fn(page,visits.first(),observed);report.groups.push({name,passed:true,observed});}catch(error){report.groups.push({name,passed:false,observed,error:error.stack});}finally{await context?.close();}}
async function download(page,name){const waiting=page.waitForEvent('download');await page.locator('[data-contact-download]').click();const d=await waiting;const p=path.join(output,name);await d.saveAs(p);const b=fs.readFileSync(p),record={file:name,bytes:b.length,sha256:sha(b),suggestedFilename:d.suggestedFilename()};report.downloads.push(record);return{...record,text:b.toString('utf8')};}
(async()=>{
const preflight=spawnSync(python,['-B','-c','import sys,importlib,json,hashlib; names=["uvicorn","fastapi","starlette","pydantic"]; print(json.dumps({"python":sys.version,"executable":sys.executable,"modules":{n:{"path":(m:=importlib.import_module(n)).__file__,"version":getattr(m,"__version__",None),"entry_sha256":hashlib.sha256(open(m.__file__,"rb").read()).hexdigest()} for n in names}}))'],{cwd:source,env,encoding:'utf8'});report.runtime={exitCode:preflight.status,stdout:preflight.stdout,stderr:preflight.stderr};assert.equal(preflight.status,0);
const port=await new Promise((resolve,reject)=>{const s=net.createServer();s.once('error',reject);s.listen(0,'127.0.0.1',()=>{const p=s.address().port;s.close(()=>resolve(p));});});origin='http://127.0.0.1:'+port;
server=spawn(python,['-B','-m','uvicorn','app:app','--host','127.0.0.1','--port',String(port),'--log-level','warning'],{cwd:source,env,stdio:['ignore','pipe','pipe']});server.stdout.on('data',b=>serverLog+=b);server.stderr.on('data',b=>serverLog+=b);
let ready=false;for(let attempt=0;attempt<100;attempt++){if(server.exitCode!==null)throw Error('Native server exited '+server.exitCode+': '+serverLog);try{const r=await fetch(origin+'/api/health');if(r.ok){report.health=await r.json();ready=true;break;}}catch{}await new Promise(r=>setTimeout(r,100));}assert.equal(ready,true,'Native FastAPI startup');assert.equal(report.health.qloo_mode,'mock');
browser=await chromium.launch({executablePath:chrome,headless:true,args:['--no-sandbox','--disable-dev-shm-usage','--disable-gpu']});report.chromium=browser.version();
await group('blank reply details remain distinct from a manually recorded contact status',async(page,visit,o)=>{
o.initialReplyDetail=await visit.locator('[data-contact-print="reply"]').textContent();
await visit.locator('[data-contact-field="status"]').selectOption('reply_recorded');
await page.emulateMedia({media:'print'});o.printStatus=await visit.locator('[data-contact-print="status"]').textContent();o.printReplyDetail=await visit.locator('[data-contact-print="reply"]').textContent();o.printDisplay=await visit.locator('.contact-print-note').evaluate(n=>getComputedStyle(n).display);await page.emulateMedia({media:'screen'});
const file=await download(page,'blank-reply.txt');o.download=file.file;o.txtHasManualStatus=file.text.includes('Caregiver contact status: Reply recorded');o.txtHasBlankDetail=file.text.includes('No reply details entered.');o.txtHasContradiction=file.text.includes('No reply recorded.');o.replyEditor=await visit.locator('[data-contact-field="reply"]').inputValue();
assert.equal(o.printStatus,'Reply recorded');assert.equal(o.replyEditor,'');assert.notEqual(o.printDisplay,'none');assert.equal(o.txtHasManualStatus,true);assert.deepEqual({initial:o.initialReplyDetail,print:o.printReplyDetail,txtDetail:o.txtHasBlankDetail,txtContradiction:o.txtHasContradiction},{initial:'No reply details entered.',print:'No reply details entered.',txtDetail:true,txtContradiction:false});
});
await group('one Blob URL setup failure keeps an eligible worksheet available for a real retry',async(page,visit,o)=>{
const reply='Caregiver-entered note retained through a failed download.';const next='Ask about the entrance before the visit.';await visit.locator('[data-contact-field="reply"]').fill(reply);
await page.evaluate(()=>{const original=URL.createObjectURL.bind(URL);window.__ttReceivingURLCalls=0;URL.createObjectURL=function(blob){window.__ttReceivingURLCalls++;if(window.__ttReceivingURLCalls===1)throw Error('Receiver-injected one-time Blob URL setup failure');return original(blob);};});
await page.locator('[data-contact-download]').click();o.notice=await page.locator('[data-contact-status]').textContent();o.disabledImmediately=await page.locator('[data-contact-download]').isDisabled();o.callsAfterFailure=await page.evaluate(()=>window.__ttReceivingURLCalls);
await visit.locator('[data-contact-field="nextStep"]').fill(next);o.disabledAfterEdit=await page.locator('[data-contact-download]').isDisabled();o.retainedReply=await visit.locator('[data-contact-field="reply"]').inputValue();o.retainedNextStep=await visit.locator('[data-contact-field="nextStep"]').inputValue();
if(!o.disabledAfterEdit){const file=await download(page,'retry-call-sheet.txt');o.retryDownload=file.file;o.retryContainsReply=file.text.includes(reply);o.retryContainsNextStep=file.text.includes(next);o.finalURLCalls=await page.evaluate(()=>window.__ttReceivingURLCalls);}else{o.retryDownload=null;o.retryNotAttemptedReason='Native button remains disabled';}
assert.match(o.notice,/Call sheet unavailable: Receiver-injected one-time Blob URL setup failure/);assert.equal(o.callsAfterFailure,1);assert.equal(o.retainedReply,reply);assert.equal(o.retainedNextStep,next);assert.equal(o.disabledImmediately,false);assert.equal(o.disabledAfterEdit,false);assert.ok(o.retryDownload);assert.equal(o.retryContainsReply,true);assert.equal(o.retryContainsNextStep,true);assert.equal(o.finalURLCalls,2);
});
})().catch(error=>{report.executionError=error.stack;}).finally(async()=>{
await Promise.allSettled(responseTasks);if(browser)await browser.close().catch(()=>{});if(server&&server.exitCode===null){server.kill('SIGTERM');await new Promise(resolve=>{const timer=setTimeout(resolve,2000);server.once('exit',()=>{clearTimeout(timer);resolve();});});if(server.exitCode===null)server.kill('SIGKILL');}
report.sourceAfter=pins();report.sourceUnchanged=JSON.stringify(report.sourceBefore)===JSON.stringify(report.sourceAfter);report.finished=new Date().toISOString();report.passed=report.groups.filter(g=>g.passed).length;report.failed=report.groups.filter(g=>!g.passed).length;report.skipped=0;report.allPassed=!report.executionError&&report.groups.length===2&&report.failed===0&&report.sourceUnchanged&&report.pageErrors.length===0&&report.externalRequests.length===0;retain('server.log',serverLog);retain('result.json',JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({passed:report.passed,failed:report.failed,allPassed:report.allPassed,sourceUnchanged:report.sourceUnchanged,executionError:report.executionError||null}));process.exitCode=report.allPassed?0:1;
});

